slot_syntax.example:
component ModalDialog(title = "Dialog Title", width = 500px) {
    size: width hug;
    radius: 16px;
    fill: #19271D;
    padding: 24px;

    text #header {
        content: title;
        font-size: 20px;
        font-weight: 700;
        color: #ffffff;
    }

    // Dynamic slot insertion point
    slot;
}

slotted_instantiation.example:
ModalDialog #confirmModal("Confirm Deployment", 560px) {
    at: center of canvas;

    // Injected directly into component's slot;
    text #dialogBody {
        content: "Are you sure you want to deploy production payload v2.4.1?";
        font-size: 14px;
        color: #9EB0A3;
        at: below #header offset 16px;
    }

    stack #buttonGroup {
        at: below #dialogBody offset 24px;
        direction: horizontal;
        gap: 12px;
        rect #btnCancel { size: 120px 40px; fill: transparent; stroke: #9EB0A3 1px; radius: 8px; }
        rect #btnConfirm { size: 160px 40px; fill: #87CC2E; radius: 8px; }
    }
}
